import { type } from "arktype"
import { LooseUser, RejectUser, DeleteUser } from "./src/schemas.ts"

const input = { name: "a", extra: 1 } as const
const valid = { name: "a" } as const

// 1. LooseUser passes extra through
const looseResult = LooseUser(input)
console.log("LooseUser({ name: 'a', extra: 1 }):", looseResult)
if (looseResult instanceof type.errors) throw new Error("FAIL: LooseUser should not return type.errors")
if (looseResult.extra !== 1) throw new Error("FAIL: LooseUser should preserve extra === 1")
console.log("  ✓ extra === 1")

// 2. RejectUser returns type.errors
const rejectResult = RejectUser(input)
console.log("RejectUser({ name: 'a', extra: 1 }):", String(rejectResult))
if (!(rejectResult instanceof type.errors)) throw new Error("FAIL: RejectUser should return type.errors")
console.log("  ✓ returned type.errors")

// 3. DeleteUser strips extra
const deleteResult = DeleteUser(input)
console.log("DeleteUser({ name: 'a', extra: 1 }):", deleteResult)
if (deleteResult instanceof type.errors) throw new Error("FAIL: DeleteUser should not return type.errors")
if ("extra" in deleteResult) throw new Error("FAIL: DeleteUser should strip extra")
console.log("  ✓ 'extra' not in result")

// 4. All three accept { name: "a" }
const looseValid = LooseUser(valid)
if (looseValid instanceof type.errors) throw new Error("FAIL: LooseUser should accept { name: 'a' }")
console.log("LooseUser({ name: 'a' }): ✓ no errors")

const rejectValid = RejectUser(valid)
if (rejectValid instanceof type.errors) throw new Error("FAIL: RejectUser should accept { name: 'a' }")
console.log("RejectUser({ name: 'a' }): ✓ no errors")

const deleteValid = DeleteUser(valid)
if (deleteValid instanceof type.errors) throw new Error("FAIL: DeleteUser should accept { name: 'a' }")
console.log("DeleteUser({ name: 'a' }): ✓ no errors")

console.log("\nAll checks passed! ✓")
